import re

def parse_duration(s: str) -> int:
    total = 0
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, s)
    for value, unit in matches:
        value = int(value)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value
